// 5-minute sweep for active/signoff issues.
// Current assignee is the source of truth for activation.
// code_review also nudges designer in parallel as a fallback lane.
const SK = $env.SUPABASE_SERVICE_ROLE_KEY;
const SUPA = '${NEXT_PUBLIC_SUPABASE_URL}';
const h = { apikey: SK, Authorization: 'Bearer ' + SK };
const TRIGGER_URL = 'http://127.0.0.1:8787/trigger-agent';
const DEDUPE_TTL_MS = 4 * 60 * 1000;

const AGENT_MAP = {
  'tester': 'tester', 'builder': 'builder', 'scout': 'scout', 'ops': 'ops',
  'kemuni-sme': 'kemuni-sme', 'vespera-sme': 'vespera-sme', 'main': 'main', 'KAOS': 'main',
  'po': 'po', 'designer': 'designer', 'auditor': 'auditor', 'deployer': 'deployer', 'ux': 'designer',
};

const staticData = $getWorkflowStaticData('global');
if (!staticData.triggered) staticData.triggered = {};
const now = Date.now();
for (const [key, ts] of Object.entries(staticData.triggered)) {
  if (now - ts > DEDUPE_TTL_MS) delete staticData.triggered[key];
}

const issues = await helpers.httpRequest({
  method: 'GET',
  url: SUPA + '/rest/v1/issues?status=in.(in_progress,code_review,product_review,released,completed)&select=id,task_key,title,assignee,status',
  headers: h
});

const results = [];
async function trigger(agentId, message, dedupeKey, issue) {
  await helpers.httpRequest({
    method: 'POST',
    url: TRIGGER_URL,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ agentId, message })
  });
  staticData.triggered[dedupeKey] = now;
  results.push({ key: issue.task_key, agent: agentId, status: issue.status, action: 'activated' });
}

for (const issue of issues) {
  const agentId = issue.assignee ? AGENT_MAP[issue.assignee] : null;
  const dedupeKey = `${issue.id}:${issue.assignee || 'unassigned'}:${issue.status}`;
  if (staticData.triggered[dedupeKey]) continue;
  if (!agentId) {
    results.push({ key: issue.task_key, status: issue.status, action: 'skipped', reason: `no agent for ${issue.assignee || 'unassigned'}` });
    continue;
  }

  const message = `Issue ${issue.task_key} is in ${issue.status} and assigned to you: ${issue.title}. Pick it up.`;
  try {
    await trigger(agentId, message, dedupeKey, issue);
    if (issue.status === 'code_review') {
      const designerKey = `${dedupeKey}:designer-fallback`;
      if (!staticData.triggered[designerKey]) {
        await helpers.httpRequest({
          method: 'POST',
          url: TRIGGER_URL,
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ agentId: 'designer', message: `Issue ${issue.task_key} is awaiting design review in code_review: ${issue.title}. Review your lane in parallel.` })
        });
        staticData.triggered[designerKey] = now;
        results.push({ key: issue.task_key, agent: 'designer', status: issue.status, action: 'activated-fallback' });
      }
    }
  } catch (e) {
    results.push({ key: issue.task_key, agent: agentId, status: issue.status, action: 'error', reason: e.message });
  }
}

return [{ json: { processed: results.length, results, timestamp: new Date().toISOString() } }];
